  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (731::BIGINT, 'Es importante asistir a clase a pesar de no ser obligatoria ya que en exámenes normalmente pregunta cosas que se mencionan, pero es súper buen profesor, explica muy bien y pregunta sobre análisis de casos que ayudan a pensar más en situaciones reales'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '5d556ea9e49767c5a598b1245723af2f991e50570950c14eed642b6b9eda1a09'::TEXT, ARRAY[3265]::BIGINT[]),
    (731::BIGINT, 'Era un poco aguevado por que se notaba que poca gente le ponía atención, pero da la clase mucho al grano y se salta mucho la teoría innecesaria; a veces para mal y otras veces para bien. Exámenes larguillos, pero es lo visto en clase y se le entiende.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '5b1c10b9bcda7fa48ad4753d4e044d7ff9a935b2ce4ce363c785a189dd48befe'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'No sé si es por el profe o por el curso, pero en muchas clases el profe explicaba muchas coasas muy rápido y no entendía prácticamente nada o muy poco, los exámenes al ser a cuaderno abierto se hacen muy sencillos eso sí, fuera de todo es un buen profe que siempre atiende a dudas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '2f9ff32689381e579804538007543fa314289372cc04b5368d785d329ce8ee63'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'Un excelente profesor, bastante divertido y aunque sus clases son un poco pesadas de entender no son imposibles. Sus exámenes son interesantes y de análisis y no califica duro. Importante estudiar eso si.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4179bd6e00117bbfb4e988bda093bc7663a7119e38c4ef077c3aefe3449fe662'::TEXT, ARRAY[3265]::BIGINT[]),
    (731::BIGINT, 'El profe es muy claro y da muchos ejemplos para entender la clase. Por lo general, le gusta enviar los exámenes a la casa, por lo que el curso es llevadero y se logra aprender más que si fueran exámenes de memoria.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2ae5012cd199d325b0003d8869c1aa8e402a0ac78ee6c8a4a2d4a434dc817e9c'::TEXT, ARRAY[3265]::BIGINT[]),
    (731::BIGINT, 'El profesor es un muy bueno en su área y además sabe explicar bastante bien, sin embargo, los temas vistos en el curso hacían que se sintiera bastante pesado e incluso aburrido (más de una vez me dormí en clases) pero el curso es bastante sencillo si se practica en clase y más fuera de esta'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2022-12-17T00:00:00+00:00'::TIMESTAMPTZ, '617d5487d2ef285e0b6004456b8b67bdf5de169b71fecd9b7da4750d9d81cd1a'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'El tema no era de mi agrado pero el profe explica muy bien y lo hace fácil de enteder. La estadística no es mi fuerte pero el profe nos hizo video tutoriales los cuales ayudaron un montón. Sabe mucho del tema y explica las veces que sean necesarias con tal de que uno entienda. Es empático y compresi'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2022-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'ba44e572a7722f5f389e8bf0507447222355f54a379961ede844a7dab0cebc05'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'Es muy buen profesor, aunque personalmente, sus clases me aburrían muchísimo. Ayuda mucho al estudiante y siempre está dispuesto a reunirse con uno.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'b1b27bdc3abe47c64a950583a6b62b4814a565f78f2a7aafb2ebc79d8378eb6e'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'Explica excelente, es sumamente paciente, ayuda mucho si usted se lo pide. Dispuesto a reunirse ya sea en hora consulta o fuera de horario. Da muy buena retroalimentación. Si pueden matriculen con él, 1000% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '8bb48a72fbfa7ecc484938c5e270a718afafad64b408dbaadcfcc94dadd86262'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'Me gustó mucho que los exámenes fueron de investigación y aunque hay que leer mucho, da bastante tiempo para hacerlos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'dcf98b2e3a5687ead10cac02b8cfa695745b6bdf31d2d12a404de6d279c5e4c1'::TEXT, ARRAY[3265]::BIGINT[]),
    (731::BIGINT, 'Es el mejor profe que he tenido en biotec, se interesa mucho por que uno en serio aprenda y si es necesario explicar algo 50 veces, él lo hará. Es muy atento con los estudiantes y hace examenes para razonar en vez de solo memorizar un montón de materia. Recomendado 50000%'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-05-27T00:00:00+00:00'::TIMESTAMPTZ, '80789886963088dd8e3ed70e0fab33af8b30bdbfcec9b891e616f728149539d4'::TEXT, ARRAY[3286]::BIGINT[]),
    (731::BIGINT, 'Se aprende bastante y las clases no son innecesariamente largas. Los exámenes son en grupo y de investigación por lo que hay que leer bastante pero da ocho días de tiempo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'cc9c0283c30baa8663539f73aec3f1b668296391a20199fe3305183b9b2a6c75'::TEXT, ARRAY[3265]::BIGINT[]),
    (731::BIGINT, 'Es muy buen profe y da clases muy claras. Los exámenes fueron de investigación, es muy comprensivo y puede llegar a dar un poco más de tiempo para entregas si las semanas están muy cargadas. Si tiene dudas le responde en poco tiempo. Se interesa que el estudiante aprenda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, '1150b3cce80d690354aef9f7e5ccea8b9292372fac82713aeaa19854149553da'::TEXT, ARRAY[3265]::BIGINT[]),
    (731::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'cf7236cef27729a9a69546d1b70d36ee3f2503f0c2befb665dabab3491ce9910'::TEXT, ARRAY[3265]::BIGINT[]),
    (731::BIGINT, 'Es increíble, ayuda demasiado, califica suave los seminarios, sabe demasiado de la materia y uno aprende mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-19T00:00:00+00:00'::TIMESTAMPTZ, '9b5fc03d6aebe34c8424444a3b9b62c772880599710e365182e6483f09e50306'::TEXT, ARRAY[3266]::BIGINT[]),
    (731::BIGINT, 'Excelente profesor él no solo quiere que uno pase, se preocupa porque enserio uno aprenda, no es solo memorizar materia te hace razonar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd6c21d10cfbcee04eae664e37e9fc0afda596da8566724ed8d9b871d1a6e6850'::TEXT, ARRAY[3265]::BIGINT[]),
