    (731::BIGINT, 'excelente'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2017-02-12T00:00:00+00:00'::TIMESTAMPTZ, '99fdeef439249f645d7c599d4aa236308106137c8757bb1b973f2a237f564ad0'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'Muy buen profe! Hay que ir a clase y prestar atención. El curso se puede pasar con buena calificación'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '30df459e82221e1859784dbb848b49917124943f7c3458ade81d4ed32ddb5d5c'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'Es un excelente profe y está GUAPISIMO. Llevar la clase con el es un mamei, lo va a amar y quere m**ar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, '3843475022bfa4f4227da055f9cfcfd3bf2f92c43e104111856d2f505d6d495c'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-30T00:00:00+00:00'::TIMESTAMPTZ, '89f1611d6971d1e70d3cb1615f6a96e671b627340c49597d057d6c4ca853f6d0'::TEXT, ARRAY[3260]::BIGINT[]),
    (731::BIGINT, 'Ayuda mucho, se preocupa por que el estudiante aprenda y los exámenes son fáciles :)'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'd10da27ada5714f96ce7f2032a27f01ecbaa65f269562d6a923b62f7fdc8999e'::TEXT, ARRAY[3260]::BIGINT[]),
